begin;
insert into public.hc_auth_institutions(id,data_institution_id,name) values('test-v292-tx','test-v292-tx','FICTICIA TEST ROLLBACK');
insert into public.hc_auth_users(username,name,default_role) values('test-v292-pro','PROFESIONAL FICTICIO','medico'),('test-v292-client','PACIENTE FICTICIO','cliente');
insert into public.hc_auth_memberships(username,institution_id,role) values('test-v292-pro','test-v292-tx','medico');
insert into public.hc_portal_clients(username,legal_name,dni,dob,document_path) values('test-v292-client','PACIENTE FICTICIO','99999991','1990-01-01','test-not-a-real-file');
insert into public.hc_tele_profiles(username,role,specialty,credential,public_visible,modes)
select 'test-v292-pro','medico','Cardiología ficticia','FICTICIA',true,jsonb_build_object('telemedicine',jsonb_build_object('enabled',true,'weekly',jsonb_build_object('days',(select jsonb_object_agg(i::text,jsonb_build_object('active',true,'start','00:00','end','23:59')) from generate_series(0,6) i)),'rates','[{"minutes":15,"amount_cents":200000},{"minutes":30,"amount_cents":350000}]'::jsonb),'office',jsonb_build_object('enabled',true,'weekly',jsonb_build_object('days',(select jsonb_object_agg(i::text,jsonb_build_object('active',true,'start','00:00','end','23:59')) from generate_series(0,6) i)),'rates','[{"minutes":15,"amount_cents":200000},{"minutes":30,"amount_cents":350000}]'::jsonb));
create temporary table tele_test_results(name text);
do $test$
declare st timestamptz=((current_date+1)::text||'T10:00:00-03:00')::timestamptz;req uuid=gen_random_uuid();v jsonb;v2 jsonb;p hc_tele_payments;failed boolean;before_sec numeric;tick jsonb;ext jsonb;provider_id uuid;
begin
 failed=false;begin perform hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st,15,req,'FICTICIO',1);exception when others then failed=true;end;if not failed then raise exception 'Payments must be disabled initially';end if;insert into tele_test_results values('Payments disabled by default');
 update hc_tele_settings set enabled=true,commission_bps=2000,cancellation_policy='CONDICIONES FICTICIAS' where id;
 v=hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st,15,req,'FICTICIO',1);
 if (v->>'total_cents')::bigint<>200000 or (v->>'platform_cents')::bigint<>40000 or (v->>'provider_cents')::bigint<>160000 then raise exception 'Split incorrect';end if;insert into tele_test_results values('Authoritative prices and exact cent split');
 v2=hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st,15,req,'FICTICIO',1);if v2->>'id'<>v->>'id' then raise exception 'Non-idempotent reservation';end if;insert into tele_test_results values('Reservation retry is idempotent');
 failed=false;begin perform hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st,15,gen_random_uuid(),'FICTICIO',1);exception when others then failed=true;end;if not failed then raise exception 'Overlapping reservation allowed';end if;insert into tele_test_results values('Concurrent overlapping slot cannot be double reserved');
 failed=false;begin perform hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st+interval '1 hour',20,gen_random_uuid(),'FICTICIO',1);exception when others then failed=true;end;if not failed then raise exception 'Invalid duration allowed';end if;insert into tele_test_results values('Unsupported duration denied');
 failed=false;begin perform hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st+interval '1 minute',15,gen_random_uuid(),'FICTICIO',1);exception when others then failed=true;end;if not failed then raise exception 'Unaligned slot allowed';end if;insert into tele_test_results values('Unaligned time denied');
 failed=false;begin perform hc292_reserve('test-v292-pro','test-v292-client','telemedicine',st+interval '1 hour',15,gen_random_uuid(),'FICTICIO',99);exception when others then failed=true;end;if not failed then raise exception 'Stale price allowed';end if;insert into tele_test_results values('Stale profile revision denied');
 v2=hc292_reserve('test-v292-pro','test-v292-client','office',st+interval '1 hour',30,gen_random_uuid(),'FICTICIO',1);
 select * into p from hc_tele_payments where visit_id=(v2->>'id')::uuid;
 if p.amount_cents<>70000 or p.provider_cents<>0 then raise exception 'Office deposit wrong';end if;insert into tele_test_results values('Office charges only platform deposit before attendance');
 select * into p from hc_tele_payments where visit_id=(v->>'id')::uuid;
 update hc_tele_payments set collector_id='TEST',consented_at=now() where id=p.id;
 failed=false;begin perform hc292_apply_tele_payment(p.id,'2920001',1,'TEST','approved',0);exception when others then failed=true;end;if not failed then raise exception 'Tampered amount accepted';end if;insert into tele_test_results values('Wrong payment amount denied');
 failed=false;begin perform hc292_apply_tele_payment(p.id,'2920001',200000,'WRONG','approved',0);exception when others then failed=true;end;if not failed then raise exception 'Wrong collector accepted';end if;insert into tele_test_results values('Wrong collector denied');
 perform hc292_apply_tele_payment(p.id,'2920000',200000,'TEST','rejected',0);
 perform hc292_apply_tele_payment(p.id,'2920001',200000,'TEST','approved',0);
 if (select status from hc_tele_visits where id=(v->>'id')::uuid)<>'confirmed' then raise exception 'Retry after rejected payment failed';end if;insert into tele_test_results values('Rejected checkout can be paid successfully on retry');
 perform hc292_apply_tele_payment(p.id,'2920001',200000,'TEST','approved',0);
 if (select count(*) from hc_tele_payment_events where payment_ref=p.id and provider_status='approved')<>1 then raise exception 'Webhook replay not idempotent';end if;insert into tele_test_results values('Webhook replay does not duplicate entitlement');
 perform hc292_apply_tele_payment(p.id,'2920002',200000,'TEST','approved',0);
 if (select review_reason from hc_tele_payment_events where payment_id='2920002')='' then raise exception 'Duplicate charge not flagged';end if;insert into tele_test_results values('Second charge flagged for refund without extra entitlement');
 insert into hc_portal_institutions(institution_id,enabled,address) values('test-v292-tx',true,'FICTICIA');
 insert into hc_portal_verifications(username,institution_id,status) values('test-v292-client','test-v292-tx','verified');
 insert into hc_portal_providers(username,institution_id,specialty,public_visible,telemedicine,weekly) values('test-v292-pro','test-v292-tx','FICTICIA',true,true,jsonb_build_object('days',(select jsonb_object_agg(i::text,jsonb_build_object('active',true,'start','00:00','end','23:59','minutes',15)) from generate_series(0,6) i))) returning id into provider_id;
 failed=false;begin insert into hc_portal_blocks(provider_id,starts_at,ends_at,created_by) values(provider_id,st,st+interval '15 minutes','test-v292-pro');exception when others then failed=true;end;if not failed then raise exception 'Institution block overlapped';end if;insert into tele_test_results values('Institution blocks respect telemedicine reservations');
 failed=false;begin insert into hc_portal_bookings(provider_id,username,starts_at,ends_at,telemedicine) values(provider_id,'test-v292-client',st,st+interval '15 minutes',true);exception when others then failed=true;end;if not failed then raise exception 'Institution booking overlapped';end if;insert into tele_test_results values('Institution bookings respect telemedicine reservations');
 update hc_tele_visits set starts_at=now()-interval '1 minute',ends_at=now()+interval '14 minutes' where id=(v->>'id')::uuid;
 perform hc292_tick((v->>'id')::uuid,'client',true);tick=hc292_tick((v->>'id')::uuid,'provider',true);
 if tick->>'status'<>'active' or (tick->>'remaining')::integer<>900 then raise exception 'Clock not started with both peers';end if;insert into tele_test_results values('Clock starts only when both peers connect');
 update hc_tele_visits set last_tick=clock_timestamp()-interval '4 seconds' where id=(v->>'id')::uuid;
 tick=hc292_tick((v->>'id')::uuid,'client',true);if (tick->>'remaining')::numeric>=898 then raise exception 'Clock did not count connected seconds';end if;insert into tele_test_results values('Clock counts server time');
 select consumed_seconds into before_sec from hc_tele_visits where id=(v->>'id')::uuid;
 update hc_tele_visits set provider_seen=clock_timestamp()-interval '20 seconds',last_tick=clock_timestamp()-interval '4 seconds' where id=(v->>'id')::uuid;
 tick=hc292_tick((v->>'id')::uuid,'client',true);
 if (select consumed_seconds from hc_tele_visits where id=(v->>'id')::uuid)<>before_sec then raise exception 'Offline peer consumed time';end if;insert into tele_test_results values('Clock pauses for offline peer');
 ext=hc292_offer_extension((v->>'id')::uuid,15);
 if (select sum(minutes) from hc_tele_payments where visit_id=(v->>'id')::uuid and status='approved' and kind='extension') is not null then raise exception 'Offer added unpaid time';end if;insert into tele_test_results values('Offering an extension adds no unpaid entitlement');
 update hc_tele_payments set collector_id='TEST',consented_at=now() where id=(ext->>'id')::uuid;
 perform hc292_apply_tele_payment((ext->>'id')::uuid,'2920003',200000,'TEST','approved',0);
 tick=hc292_tick((v->>'id')::uuid,'provider',true);
 if (tick->>'entitledSeconds')::integer<>1800 then raise exception 'Extension entitlement wrong';end if;insert into tele_test_results values('Accepted and approved extension adds exactly its paid minutes');
 perform hc292_apply_tele_payment((ext->>'id')::uuid,'2920003',200000,'TEST','approved',0);
 tick=hc292_tick((v->>'id')::uuid,'provider',true);if (tick->>'entitledSeconds')::integer<>1800 then raise exception 'Extension replay duplicated time';end if;insert into tele_test_results values('Extension webhook replay adds no extra minutes');
 perform hc292_apply_tele_payment(p.id,'2920001',200000,'TEST','refunded',200000);
 if (select status from hc_tele_visits where id=(v->>'id')::uuid)<>'payment_review' then raise exception 'Refund did not revoke session';end if;insert into tele_test_results values('Refunded payment closes access to further consultation');
end$test$;
select count(*) as passed,jsonb_agg(name) as checks from tele_test_results;
rollback;